 public static DockPlacement ChooseDockPlacement(Rect widget,Rect area){return ChooseDockPlacement(widget,area,4);}
 public static DockPlacement ChooseDockPlacement(Rect widget,Rect area,int count){count=Math.Max(3,Math.Min(4,count));double length=12+56*count;DockPlacement corner;if(TryCornerDock(widget,area,count,out corner))return corner;double gap=4;string[] sides={"left","right","bottom","top"};double[] room={Math.Max(0,widget.Left-area.Left-gap),Math.Max(0,area.Right-widget.Right-gap),Math.Max(0,area.Bottom-widget.Bottom-gap),Math.Max(0,widget.Top-area.Top-gap)};int chosen=-1;for(int i=0;i<4;i++){bool vertical=i<2;if(room[i]>=78&&(vertical?area.Height:area.Width)>=length){chosen=i;break;}}if(chosen<0){chosen=0;for(int i=1;i<4;i++)if(room[i]>room[chosen])chosen=i;}bool tall=chosen<2;double scale=Math.Min(1,Math.Min(room[chosen]/78,(tall?area.Height:area.Width)/length));scale=Math.Max(.4,scale);double width=(tall?78:length)*scale,height=(tall?length:78)*scale;double x=tall?(chosen==0?widget.Left-width-gap:widget.Right+gap):widget.Left+(widget.Width-width)/2;double y=tall?widget.Top+(widget.Height-height)/2:(chosen==2?widget.Bottom+gap:widget.Top-height-gap);x=Math.Max(area.Left,Math.Min(area.Right-width,x));y=Math.Max(area.Top,Math.Min(area.Bottom-height,y));return new DockPlacement{Side=sides[chosen],X=x,Y=y,Width=width,Height=height,Scale=scale};}
 public static bool TryCornerDock(Rect widget,Rect area,out DockPlacement placement){return TryCornerDock(widget,area,4,out placement);}
 public static bool TryCornerDock(Rect widget,Rect area,int count,out DockPlacement placement){count=Math.Max(3,Math.Min(4,count));placement=new DockPlacement();double left=widget.Left-area.Left,right=area.Right-widget.Right,top=widget.Top-area.Top,bottom=area.Bottom-widget.Bottom;bool nearLeft=left<96&&left<=right,nearRight=right<96&&right<left,nearTop=top<96&&top<=bottom,nearBottom=bottom<96&&bottom<top;if(!(nearLeft||nearRight)||!(nearTop||nearBottom))return false;string side=nearTop?(nearLeft?"corner-tl":"corner-tr"):(nearLeft?"corner-bl":"corner-br");double angle=side=="corner-tl"?0:side=="corner-tr"?Math.PI/2:side=="corner-br"?Math.PI:Math.PI*1.5;Point center=new Point(widget.Left+widget.Width/2,widget.Top+widget.Height/2);double rx=widget.Width/2+34,ry=widget.Height/2+34;Point[] points=new Point[count];Rect exclusion=widget;exclusion.Inflate(4,4);bool clear=false;for(int attempt=0;attempt<60;attempt++){clear=true;for(int i=0;i<count;i++){double a=angle+i*Math.PI/(2*(count-1));points[i]=new Point(center.X+rx*Math.Cos(a),center.Y+ry*Math.Sin(a));var button=new Rect(points[i].X-26,points[i].Y-26,52,52);if(button.IntersectsWith(exclusion))clear=false;if(i>0&&(points[i]-points[i-1]).Length<58)clear=false;}if(clear)break;rx*=1.05;ry*=1.05;}if(!clear)return false;double minX=points.Min(p=>p.X)-30,minY=points.Min(p=>p.Y)-30,maxX=points.Max(p=>p.X)+30,maxY=points.Max(p=>p.Y)+30;double dx=nearLeft?Math.Max(0,area.Left-minX):Math.Min(0,area.Right-maxX),dy=nearTop?Math.Max(0,area.Top-minY):Math.Min(0,area.Bottom-maxY);for(int i=0;i<count;i++)points[i]=new Point(points[i].X+dx,points[i].Y+dy);minX+=dx;maxX+=dx;minY+=dy;maxY+=dy;if(minX<area.Left-.001||minY<area.Top-.001||maxX>area.Right+.001||maxY>area.Bottom+.001)return false;for(int i=0;i<count;i++)points[i]=new Point(points[i].X-minX-26,points[i].Y-minY-26);placement=new DockPlacement{Side=side,X=minX,Y=minY,Width=maxX-minX,Height=maxY-minY,Scale=1,Points=points,Anchor=new Point(center.X-minX,center.Y-minY)};return true;}
 void BuildMiniDock(){miniActions=Row();miniDockDelay=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(1000)};miniDockDelay.Tick+=(s,e)=>{miniDockDelay.Stop();if(MiniDockPointerSafe()){miniDockDelay.Start();return;}HideMiniDock(false);};miniLayout.MouseEnter+=(s,e)=>ShowMiniDock();miniLayout.MouseLeave+=(s,e)=>DelayMiniDockHide();LocationChanged+=(s,e)=>PositionMiniDock();SizeChanged+=(s,e)=>PositionMiniDock();IsVisibleChanged+=(s,e)=>{if(!IsVisible)HideMiniDock(true);};StateChanged+=(s,e)=>{if(WindowState==WindowState.Minimized)HideMiniDock(true);};Closed+=(s,e)=>{miniDockDelay.Stop();if(miniDock!=null){try{miniDock.Close();}catch(InvalidOperationException){}}};}
