 public static Rect MiniDockHoverArea(Rect widget,Rect dock){var area=Rect.Union(widget,dock);area.Inflate(18,18);return area;}
 bool MiniDockPointerSafe(){
  if(miniLayout.IsMouseOver||(miniDock!=null&&miniDock.IsMouseOver))return true;
  if(miniDock==null||!miniDock.IsVisible||!IsVisible)return false;
  try{var cursor=System.Windows.Forms.Cursor.Position;var bounds=new Rect(PointToScreen(new Point(0,0)),PointToScreen(new Point(ActualWidth,ActualHeight)));bounds=MiniDockHoverArea(bounds,new Rect(miniDock.PointToScreen(new Point(0,0)),miniDock.PointToScreen(new Point(miniDock.ActualWidth,miniDock.ActualHeight))));return bounds.Contains(new Point(cursor.X,cursor.Y));}catch{return false;}
 }
