 void CreateMiniDock(){if(miniDock!=null)return;miniDock=new Window{Title="Majestic · Управление",Owner=this,WindowStyle=WindowStyle.None,AllowsTransparency=true,Background=Brush("#00000000"),ShowInTaskbar=false,ShowActivated=false,ResizeMode=ResizeMode.NoResize,Topmost=Topmost,Resources=Resources};orbitCanvas=new Canvas{Width=78,Height=236,ClipToBounds=true};miniDock.Content=new Viewbox{Child=orbitCanvas,Stretch=Stretch.Uniform};Path ignored;Button previous=OrbitButton("Предыдущая запись","M 17,4 L 8,13 L 17,22",()=>CycleMini(-1),out ignored);Button next=OrbitButton("Следующая запись","M 9,4 L 18,13 L 9,22",()=>CycleMini(1),out ignored);Button expand=OrbitButton("Развернуть","M 5,21 L 21,5 M 9,5 L 21,5 L 21,17",()=>SetCompact(false),out ignored);orbitPause=OrbitButton("Пауза","M 9,5 L 9,21 M 17,5 L 17,21",PauseOrbitTimer,out orbitPauseIcon);foreach(var button in new[]{previous,next,expand,orbitPause}){var bubble=new Border{Width=52,Height=52,Child=button,RenderTransform=new TranslateTransform()};orbitBubbles.Add(bubble);orbitCanvas.Children.Add(bubble);}miniDock.MouseEnter+=(s,e)=>{miniDockDelay.Stop();ShowMiniDock();};miniDock.MouseLeave+=(s,e)=>DelayMiniDockHide();PositionMiniDock();UpdateOrbitPause();}
 void PlaceOrbitBubbles(string side){int count=MiniPauseVisible?4:3;if(orbitPlacement.Points!=null){orbitCanvas.Width=orbitPlacement.Width;orbitCanvas.Height=orbitPlacement.Height;for(int i=0;i<count;i++){Canvas.SetLeft(orbitBubbles[i],orbitPlacement.Points[i].X);Canvas.SetTop(orbitBubbles[i],orbitPlacement.Points[i].Y);}return;}bool vertical=side=="left"||side=="right";orbitCanvas.Width=vertical?78:12+56*count;orbitCanvas.Height=vertical?12+56*count:78;bool bowOut=side=="left"||side=="top";for(int i=0;i<count;i++){double curve=(i==0||i==count-1)?18:4;if(!bowOut)curve=22-curve;Canvas.SetLeft(orbitBubbles[i],vertical?curve:8+56*i);Canvas.SetTop(orbitBubbles[i],vertical?8+56*i:curve);}}
 void PositionMiniDock(){if(miniDock==null||!compact)return;var placement=ChooseDockPlacement(new Rect(base.Left,base.Top,Math.Max(1,ActualWidth),Math.Max(1,ActualHeight)),CurrentWorkArea(),MiniPauseVisible?4:3);bool changed=orbitSide!=placement.Side;orbitSide=placement.Side;orbitPlacement=placement;PlaceOrbitBubbles(orbitSide);miniDock.Width=placement.Width;miniDock.Height=placement.Height;miniDock.Left=placement.X;miniDock.Top=placement.Y;if(changed&&miniDock.IsVisible)AnimateOrbit(true,true);}
 void AnimateOrbit(bool show,bool fresh){for(int i=0;i<orbitBubbles.Count;i++){var bubble=orbitBubbles[i];var shift=(TranslateTransform)bubble.RenderTransform;bool vertical=orbitSide=="left"||orbitSide=="right";double direction=orbitSide=="left"||orbitSide=="top"?32:-32;Vector inward=orbitPlacement.Points==null?new Vector(vertical?direction:0,vertical?0:direction):orbitPlacement.Anchor-new Point(Canvas.GetLeft(bubble)+26,Canvas.GetTop(bubble)+26);if(inward.Length>0)inward.Normalize();inward*=32;Vector tangent=new Vector(-inward.Y,inward.X)*.2;if(fresh){bubble.BeginAnimation(UIElement.OpacityProperty,null);bubble.Opacity=0;shift.BeginAnimation(TranslateTransform.XProperty,null);shift.BeginAnimation(TranslateTransform.YProperty,null);shift.X=inward.X;shift.Y=inward.Y;}int delay=show?i*35:(3-i)*18;var easing=new CubicEase{EasingMode=EasingMode.EaseOut};bubble.BeginAnimation(UIElement.OpacityProperty,new DoubleAnimation(show?1:0,TimeSpan.FromMilliseconds(show?190:130)){BeginTime=TimeSpan.FromMilliseconds(delay),EasingFunction=easing});if(orbitPlacement.Points!=null&&show){shift.BeginAnimation(TranslateTransform.XProperty,ArcShift(shift.X,inward.X*.25+tangent.X,delay));shift.BeginAnimation(TranslateTransform.YProperty,ArcShift(shift.Y,inward.Y*.25+tangent.Y,delay));}else{shift.BeginAnimation(TranslateTransform.XProperty,new DoubleAnimation(show?0:inward.X,TimeSpan.FromMilliseconds(show?260:170)){BeginTime=TimeSpan.FromMilliseconds(delay),EasingFunction=easing});shift.BeginAnimation(TranslateTransform.YProperty,new DoubleAnimation(show?0:inward.Y,TimeSpan.FromMilliseconds(show?260:170)){BeginTime=TimeSpan.FromMilliseconds(delay),EasingFunction=easing});}}}
 DoubleAnimationUsingKeyFrames ArcShift(double start,double bend,int delay){var path=new DoubleAnimationUsingKeyFrames{BeginTime=TimeSpan.FromMilliseconds(delay)};path.KeyFrames.Add(new LinearDoubleKeyFrame(start,KeyTime.FromTimeSpan(TimeSpan.Zero)));path.KeyFrames.Add(new SplineDoubleKeyFrame(bend,KeyTime.FromTimeSpan(TimeSpan.FromMilliseconds(150)),new KeySpline(.2,.7,.3,1)));path.KeyFrames.Add(new SplineDoubleKeyFrame(0,KeyTime.FromTimeSpan(TimeSpan.FromMilliseconds(280)),new KeySpline(.2,.7,.3,1)));return path;}
 void ShowMiniDock(){if(gameInputLocked||!compact||!IsVisible||WindowState==WindowState.Minimized)return;miniDockDelay.Stop();CreateMiniDock();bool appearing=!miniDock.IsVisible;miniDockAnimation++;miniDock.Topmost=Topmost;PositionMiniDock();UpdateOrbitPause();if(appearing)miniDock.Show();AnimateOrbit(true,appearing);}
